import queue

class Solve:

    def __init__(self) -> None:
        self.x = 0;
        self.dem = 0;

    def vao(self) -> None:
        self.x = int(input());

    def lam(self) -> None:
        tong = 0;
        x_abs = abs(self.x);
        while(tong < x_abs or (tong - x_abs) % 2 != 0):
            self.dem += 1;
            tong += self.dem;

    def ra(self) -> None:
        print(self.dem);


def main():
    p = Solve();
    p.vao();
    p.lam();
    p.ra();

main();

from math import ceil

x = abs(int(input()))

def is_even(a):
    return a % 2 == 0

def calc_sum(n):
    return n * (n + 1) // 2

def check(a, x):
    return (not is_even(a) and not is_even(x)) or (is_even(a) and is_even(x))

if x == 0:
    print(0)
else:
    n = (-1 + (1 + 8 * x) ** 0.5) / 2
    ceil_n = ceil(n)

    if check(calc_sum(ceil_n), x):
        print(ceil_n)
    else:
        if check(calc_sum(ceil_n + 1), x):
            print(ceil_n + 1)
        else:
            print(ceil_n + 2)

